        """Links a Product and a Tag (product_tags)."""
        self._find(product_id)
        if self._uow.tags.find_by_id(tag_id) is None:
            raise NotFoundError("Tag", tag_id)
        if self._uow.product_tags.find_by_product_id_and_tag_id(product_id, tag_id) is not None:
            raise ConflictError("Product", "is already linked to this Tag", ("tag_id",))
        self._uow.product_tags.insert(ProductTag(product_id=product_id, tag_id=tag_id))

    def remove_tag(self, product_id: int, tag_id: int) -> None:
        """Removes the link between a Product and a Tag (product_tags)."""
        link = self._uow.product_tags.find_by_product_id_and_tag_id(product_id, tag_id)
