"""Operations on tags: what each one checks before it writes."""

from typing import Any

from app.errors import ConflictError, FieldError, NotFoundError, ValidationFailedError
from app.paging import Page
from app.product_tag.entity import ProductTag
from app.tag.dtos import TagCreate, TagRead, TagUpdate
from app.tag.entity import Tag
from app.unit_of_work import UnitOfWork

# Columns a client may send: the database fills the others
_FIELDS = frozenset({"label"})


class TagService:
    """Operations on tags. It never commits: the caller owns the transaction."""

    def __init__(self, uow: UnitOfWork) -> None:
        self._uow = uow

    def _validate_all(self, values: dict[str, Any], current: Tag | None) -> None:
        """Checks the values against the rules of the "tags" table; raises ValidationFailedError with every problem."""
        creating = current is None
        errors: list[FieldError] = []
        for name in values.keys() - _FIELDS:
            errors.append(FieldError(name, "is not a field of Tag"))
        if not creating:
            for name in values.keys() & {"id"}:
                errors.append(FieldError(name, "cannot be changed"))
        value = values.get("label")
        if value is None:
            if creating or "label" in values:
                errors.append(FieldError("label", "is required"))
        else:
            if isinstance(value, str) and len(value) > 30:
                errors.append(FieldError("label", "is longer than 30 characters"))
        if errors:
            raise ValidationFailedError("Tag", errors)

    def _check(self, values: dict[str, Any], current: Tag | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        self._validate_all(values, current)

    def _find(self, id: int) -> Tag:
        """The Tag with this key; NotFoundError when there is none."""
        entity = self._uow.tags.find_by_id(id)
        if entity is None:
            raise NotFoundError("Tag", id)
        return entity

    @staticmethod
    def _read(entity: Tag) -> TagRead:
        """The Tag as services return it."""
        return TagRead.model_validate(entity)

    def create_tag(self, data: TagCreate) -> TagRead:
        """Stores a new Tag after checking it."""
        values = data.model_dump(exclude_unset=True)
        self._check(values, None)
        created = self._uow.tags.insert(Tag(**values))
        return self._read(created)

    def get_tag(self, id: int) -> TagRead:
        """The Tag with this key; NotFoundError when there is none."""
        return self._read(self._find(id))

    def list_tags(self, offset: int = 0, limit: int = 50) -> Page[TagRead]:
        """A page of tags, by primary key."""
        page = self._uow.tags.list(offset, limit)
        return Page(items=[self._read(entity) for entity in page.items], total=page.total, offset=page.offset, limit=page.limit)

    def update_tag(self, id: int, data: TagUpdate) -> TagRead:
        """Changes the given values of a Tag."""
        values = data.model_dump(exclude_unset=True)
        current = self._find(id)
        self._check(values, current)
        for name, value in values.items():
            setattr(current, name, value)
        updated = self._uow.tags.update(current)
        return self._read(updated)

    def delete_tag(self, id: int) -> None:
        """Deletes a Tag."""
        current = self._find(id)
        self._uow.tags.delete(current)

    def add_product(self, tag_id: int, product_id: int) -> None:
        """Links a Tag and a Product (product_tags)."""
        self._find(tag_id)
        if self._uow.products.find_by_id(product_id) is None:
            raise NotFoundError("Product", product_id)
        if self._uow.product_tags.find_by_product_id_and_tag_id(product_id, tag_id) is not None:
            raise ConflictError("Tag", "is already linked to this Product", ("product_id",))
        self._uow.product_tags.insert(ProductTag(tag_id=tag_id, product_id=product_id))

    def remove_product(self, tag_id: int, product_id: int) -> None:
        """Removes the link between a Tag and a Product (product_tags)."""
        link = self._uow.product_tags.find_by_product_id_and_tag_id(product_id, tag_id)
        if link is None:
            raise NotFoundError("ProductTag", (product_id, tag_id))
        self._uow.product_tags.delete(link)

